Operations' two extras are not in this crate. The node's world grants only `Notifier<'digest'>`. There is no filesystem or HTTP import, and adding either would give the node authority its contract doesn't include. On `wasm32-unknown-unknown` there is no file access to write `/var/log/aap/node-inputs.log` anyway. If you want them, the graph needs a logging or `http-client` capability on this node, and the host should do the logging.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut msg = String::new();
        msg.push_str("Digest ");
        msg.push_str(&composed.date);
        msg.push_str("\n");
        msg.push_str(&composed.overview);
        for e in composed.entries.iter().filter(|e| e.kept) {
            msg.push_str("\n- ");
            msg.push_str(&e.title);
            msg.push_str(" (");
            msg.push_str(&e.link);
            msg.push_str(")");
        }

        let published = crate::aap::caps::notifier::notify(&msg);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
